def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    counts = Counter(v for row in g for v in row)
    bg = counts.most_common(1)[0][0]
    # The ray is indicated by two same-colored diagonal cells; continue their
    # diagonal vector, changing only background cells.
    options = []
    for r in range(h):
        for c in range(w):
            color = g[r][c]
            if color == bg:
                continue
            for dr, dc in ((1, -1), (1, 1)):
                rr, cc = r + dr, c + dc
                if 0 <= rr < h and 0 <= cc < w and g[rr][cc] == color:
                    # Prefer the 7 marker pattern where present, otherwise the
                    # diagonal pair that lies furthest down in the grid.
                    options.append((color == 7, rr, color, rr, cc, dr, dc))
    if options:
        _, _, color, r, c, dr, dc = max(options)
        r += dr
        c += dc
        while 0 <= r < h and 0 <= c < w:
            if g[r][c] == bg:
                g[r][c] = color
            r += dr
            c += dc
    return g
